export type UserRole = 'owner' | 'admin' | 'member' | 'contributor' | 'viewer' | 'evaluator'

export type User = {
  id: string
  email: string
  displayName: string
  avatarUrl?: string
  createdAt: string
}

export type UserProfile = {
  id: string
  userId: string
  displayName: string
  bio?: string
  avatarUrl?: string
  skills: string[]
  interests: string[]
  locale: string
  themeMode: 'light' | 'dark' | 'system'
  accentPreset: string
  notificationPreferences: NotificationPreferences
  createdAt: string
  updatedAt: string
}

export type NotificationPreferences = {
  invite: ChannelPrefs
  approval: ChannelPrefs
  assignment: ChannelPrefs
  evaluation: ChannelPrefs
  completion: ChannelPrefs
  billing: ChannelPrefs
  admin: ChannelPrefs
  ai: ChannelPrefs
  marketplace: ChannelPrefs
}

export type ChannelPrefs = {
  inApp: boolean
  email: boolean
  push: boolean
  digest: boolean
}
